INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Anwendersoftware immer für technische Nutzer gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Laien konzipiert"}, {"text": "Ja", "correct": false, "because": "Breite Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Anwendersoftware?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": true, "because": "Erleichtert Nutzung"}, {"text": "Systemoptimierung", "correct": false, "because": "Nicht primär"}, {"text": "Code-Effizienz", "correct": false, "because": "Entwicklerfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gehören zur Anwendersoftware?', 5, '[{"text": "Textverarbeitung", "correct": true, "because": "Für Endnutzer"}, {"text": "Tabellenkalkulation", "correct": true, "because": "Alltägliche Nutzung"}, {"text": "Betriebssystem", "correct": false, "because": "Systemsoftware"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anwendersoftware ist benutzerorientiert. b) Sie ist immer kostenlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Entwicklung von Anwendersoftware?', 4, '[{"text": "Benutzerfreundlichkeit", "correct": false, "because": "Kernprinzip"}, {"text": "Kompatibilität", "correct": false, "because": "Wichtig für Nutzung"}, {"text": "Hardware-Design", "correct": true, "because": "Nicht Softwarefokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anwendersoftware plattformabhängig sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Abhängig vom System"}, {"text": "Nein", "correct": false, "because": "Oft plattformspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Software gehört nicht zur Anwendersoftware?', 3, '[{"text": "Compiler", "correct": true, "because": "Entwicklertool"}, {"text": "Webbrowser", "correct": false, "because": "Für Endnutzer"}, {"text": "E-Mail-Client", "correct": false, "because": "Anwenderorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Entwicklung von Anwendersoftware?', 5, '[{"text": "Benutzeroberfläche", "correct": true, "because": "Erleichtert Bedienung"}, {"text": "Usability-Tests", "correct": true, "because": "Sichert Nutzerfreundlichkeit"}, {"text": "Kernel-Programmierung", "correct": false, "because": "Systemebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Anwendersoftware ist für den Alltag. b) Sie ist immer Open Source. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer Open Source"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Anwendersoftware unwichtig?', 4, '[{"text": "Intuitive Bedienung", "correct": false, "because": "Hauptmerkmal"}, {"text": "Funktionalität", "correct": false, "because": "Erfüllt Nutzerbedarf"}, {"text": "Systemtreiber", "correct": true, "because": "Systemsoftware"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Anwendersoftware grafisch sein?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kommandozeile möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend grafisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Anwendersoftware?', 4, '[{"text": "Einfache Nutzung", "correct": true, "because": "Für Laien gedacht"}, {"text": "Produktivität", "correct": true, "because": "Unterstützt Aufgaben"}, {"text": "Hardware-Optimierung", "correct": false, "because": "Nicht Hauptziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anwendersoftware immer teuer ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren"}, {"text": "Ja", "correct": false, "because": "Auch kostenlos verfügbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Anwendersoftware?', 3, '[{"text": "Benutzererfahrung", "correct": true, "because": "Entscheidend für Akzeptanz"}, {"text": "Code-Optimierung", "correct": false, "because": "Sekundär"}, {"text": "Entwicklungskosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anwendersoftware unterstützt alltägliche Aufgaben. b) Sie ist für Programmierer gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht nur für Programmierer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat schlecht gestaltete Anwendersoftware?', 5, '[{"text": "Schwierige Bedienung", "correct": true, "because": "Frustriert Nutzer"}, {"text": "Geringe Akzeptanz", "correct": true, "because": "Wenig intuitiv"}, {"text": "Schnelle Entwicklung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Anwendersoftware unwichtig?', 3, '[{"text": "Benutzerfreundlichkeit", "correct": false, "because": "Kernmerkmal"}, {"text": "Funktionalität", "correct": false, "because": "Erfüllt Zweck"}, {"text": "Kernelzugriff", "correct": true, "because": "Systemebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Anwendersoftware webbasiert sein?', 3, '[{"text": "Ja", "correct": true, "because": "Z.B. Online-Tools"}, {"text": "Nein", "correct": false, "because": "Nicht eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anwendersoftware spezialisierte Kenntnisse erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Für Laien gedacht"}, {"text": "Ja", "correct": false, "because": "Einfachheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art wähle ich für alltägliche Büroaufgaben?', 4, '[{"text": "Office-Software", "correct": true, "because": "Text, Tabellen etc."}, {"text": "Entwicklungsumgebung", "correct": false, "because": "Für Programmierer"}, {"text": "Betriebssystem", "correct": false, "because": "Systemsoftware"}]');
